if (block >= lfs->cfg->block_count) {
    return LFS_ERR_INVAL;
}
if (off + size > lfs->cfg->block_size) {
    return LFS_ERR_INVAL;
}

// Initialize comparison result
int cmp = LFS_CMP_EQ;

// Read data in chunks using cache-aware reads
while (size > 0) {
    // Determine how much to read in this iteration
    lfs_size_t chunk_size = size;
    lfs_off_t current_off = off;

    // Check if we can use the read cache
    if (rcache && rcache->block == block) {
        // Calculate overlap with cached data
        lfs_off_t cache_start = rcache->off;
        lfs_off_t cache_end = rcache->off + rcache->size;
        lfs_off_t req_start = off;
        lfs_off_t req_end = off + chunk_size;

        if (req_start >= cache_start && req_start < cache_end) {
            // Data is in cache, use it
            lfs_size_t cache_offset = req_start - cache_start;
            lfs_size_t available = cache_end - req_start;
            chunk_size = std::min(chunk_size, available);

            // Compare cached data with buffer
            const uint8_t* cache_data = &rcache->buffer[cache_offset];
            int local_cmp = std::memcmp(buffer, cache_data, chunk_size);
            if (local_cmp != 0) {
                cmp = (local_cmp < 0) ? LFS_CMP_LT : LFS_CMP_GT;
                break;
            }

            // Update pointers for next iteration
            buffer = static_cast<const uint8_t*>(buffer) + chunk_size;
            off += chunk_size;
            size -= chunk_size;
            continue;
        }
    }

    // If we get here, we need to read from block device
    // Determine optimal read size considering hint and cache
    lfs_size_t read_size = lfs->cfg->read_size;
    if (hint > 0) {
        read_size = std::max(read_size, hint);
    }
    if (rcache) {
        read_size = std::max(read_size, lfs->cfg->cache_size);
    }
    chunk_size = std::min(chunk_size, read_size);

    // Read data from block device
    uint8_t* read_buffer = rcache ? rcache->buffer : static_cast<uint8_t*>(lfs->cfg->read_buffer);
    int err = lfs->cfg->read(lfs->cfg, block, current_off, read_buffer, chunk_size);
    if (err != LFS_ERR_OK) {
        return err;
    }

    // Update read cache if available
    if (rcache) {
        rcache->block = block;
        rcache->off = current_off;
        rcache->size = chunk_size;
    }

    // Compare read data with buffer
    int local_cmp = std::memcmp(buffer, read_buffer, chunk_size);
    if (local_cmp != 0) {
        cmp = (local_cmp < 0) ? LFS_CMP_LT : LFS_CMP_GT;
        break;
    }

    // Update pointers for next iteration
    buffer = static_cast<const uint8_t*>(buffer) + chunk_size;
    off += chunk_size;
    size -= chunk_size;
}

return cmp;

